class Solution {
    private String text;
    private int index;
    private Map<String,Integer> values;
    public List<String> basicCalculatorIV(String expression,String[] evalvars,int[] evalints){
        text=expression;
        index=0;
        values=new HashMap<>();
        for(int i=0;i<evalvars.length;i++)values.put(evalvars[i],evalints[i]);
        Map<String,Integer> polynomial=parseExpression();
        List<String> keys=new ArrayList<>();
        for(String key:polynomial.keySet())if(polynomial.get(key)!=0)keys.add(key);
        keys.sort((a,b)->{
            int da=degree(a),db=degree(b);
            return da!=db?Integer.compare(db,da):a.compareTo(b);
        });
        List<String> answer=new ArrayList<>();
        for(String key:keys)answer.add(polynomial.get(key)+(key.isEmpty()?"":"*"+key));
        return answer;
    }
    private Map<String,Integer> parseExpression(){
        Map<String,Integer> result=parseTerm();
        while(true){
            skip();
            if(index>=text.length()||(text.charAt(index)!='+'&&text.charAt(index)!='-'))return result;
            char operation=text.charAt(index++);
            result=add(result,parseTerm(),operation=='+'?1:-1);
        }
    }
    private Map<String,Integer> parseTerm(){
        Map<String,Integer> result=parseFactor();
        while(true){
            skip();
            if(index>=text.length()||text.charAt(index)!='*')return result;
            index++;
            result=multiply(result,parseFactor());
        }
    }
    private Map<String,Integer> parseFactor(){
        skip();
        if(text.charAt(index)=='('){
            index++;
            Map<String,Integer> result=parseExpression();
            skip();
            index++;
            return result;
        }
        int start=index;
        if(Character.isDigit(text.charAt(index))){
            while(index<text.length()&&Character.isDigit(text.charAt(index)))index++;
            return single("",Integer.parseInt(text.substring(start,index)));
        }while(index<text.length()&&Character.isLetter(text.charAt(index)))index++;
        String variable=text.substring(start,index);
        return values.containsKey(variable)?single("",values.get(variable)):single(variable,1);
    }
    private void skip(){
        while(index<text.length()&&text.charAt(index)==' ')index++;
    }
    private Map<String,Integer> single(String key,int coefficient){
        Map<String,Integer> result=new HashMap<>();
        result.put(key,coefficient);
        return result;
    }
    private Map<String,Integer> add(Map<String,Integer> a,Map<String,Integer> b,int sign){
        Map<String,Integer> result=new HashMap<>(a);
        for(Map.Entry<String,Integer> entry:b.entrySet())result.merge(entry.getKey(),sign*entry.getValue(),Integer::sum);
        return result;
    }
    private Map<String,Integer> multiply(Map<String,Integer> a,Map<String,Integer> b){
        Map<String,Integer> result=new HashMap<>();
        for(Map.Entry<String,Integer> x:a.entrySet())for(Map.Entry<String,Integer> y:b.entrySet())result.merge(mergeKey(x.getKey(),y.getKey()),x.getValue()*y.getValue(),Integer::sum);
        return result;
    }
    private String mergeKey(String a,String b){
        List<String> variables=new ArrayList<>();
        StringTokenizer first=new StringTokenizer(a,"*");
        while(first.hasMoreTokens())variables.add(first.nextToken());
        StringTokenizer second=new StringTokenizer(b,"*");
        while(second.hasMoreTokens())variables.add(second.nextToken());
        Collections.sort(variables);
        return String.join("*",variables);
    }
    private int degree(String key){
        if(key.isEmpty())return 0;
        int result=1;
        for(int i=0;i<key.length();i++)if(key.charAt(i)=='*')result++;
        return result;
    }
}

